      <h2 id="trail-h">Footprints that walk the page</h2>
      <p class="lede">On the real landing page, GSAP's MotionPath and ScrollTrigger place these prints along one SVG path that runs the whole page in the left gutter. Prints appear as you scroll, so the trail also works as the scroll progress bar. Below is the loop version for the hero or the booth.</p>
    </div>
    <div class="trail-box">
      <div class="toggle" role="group" aria-label="Trail style">
        <button type="button" data-mode="prints" aria-pressed="true">Footprints</button>
        <button type="button" data-mode="route" aria-pressed="false">Route line (in-app)</button>
      </div>
      <svg viewBox="0 0 800 240" role="img" aria-label="A winding trail across the page">
        <defs>
          <g id="foot">
            <ellipse cx="0" cy="-2" rx="4.6" ry="6.6"/>
            <ellipse cx="0" cy="8" rx="3.4" ry="3.9"/>
            <circle cx="-3.6" cy="-10.2" r="1.35"/><circle cx="-1.2" cy="-11.4" r="1.45"/><circle cx="1.4" cy="-11.2" r="1.35"/><circle cx="3.6" cy="-9.8" r="1.2"/>
          </g>
        </defs>
        <path id="trailPath" d="M -10 200 C 110 210, 150 60, 290 70 S 470 215, 590 160 S 740 40, 810 60" fill="none" stroke="var(--line)" stroke-width="1.5" stroke-dasharray="3 7"/>
        <g id="prints" fill="var(--primary)"></g>
        <g id="routeLayer" hidden>
          <path d="M -10 200 C 110 210, 150 60, 290 70 S 470 215, 590 160 S 740 40, 810 60" fill="none" stroke="#F48057" stroke-width="6" stroke-linecap="round" opacity=".25"/>
          <path class="route-dash" d="M -10 200 C 110 210, 150 60, 290 70 S 470 215, 590 160 S 740 40, 810 60" fill="none" stroke="#F48057" stroke-width="5" stroke-linecap="round"/>
          <circle cx="290" cy="70" r="7" fill="var(--card)" stroke="var(--primary)" stroke-width="3"/>
          <circle cx="590" cy="160" r="7" fill="var(--card)" stroke="var(--primary)" stroke-width="3"/>
          <circle r="9" fill="#F48057" stroke="var(--card)" stroke-width="3">
