      {index < PEOPLE.length - 1 ? (
        <svg viewBox="0 0 8 56" className="mx-auto h-14 w-2 lg:hidden" aria-hidden="true">
          <line x1="4" y1="2" x2="4" y2="54" stroke={CORAL} strokeWidth="4" strokeLinecap="round" strokeDasharray="2 10" />
        </svg>
      ) : null}
